using MudRunner.Audio;
using MudRunner.UI;
using UnityEngine;

namespace MudRunner.Game
{
    /// <summary>
    /// Lives in the Game scene. Creates the GameManager and starts the requested world.
    /// Scene content is intentionally minimal (camera, light, this object): everything else is generated by code.
    /// The UI layer (camera rig, HUD, menus, debug window) is created at runtime by <see cref="UiBootstrap"/>.
    /// </summary>
    public sealed class GameBootstrap : MonoBehaviour
    {
        public WorldKind world = WorldKind.ProvingGround;
        public string vehicle = "utility";
        public bool autoStart = true;
        [Tooltip("Create the camera rig, HUD, menus and debug window.")]
        public bool installUi = true;
        [Tooltip("Open the main menu over the freshly started world (also see GameSession.ShowMainMenuOnStart).")]
        public bool showMainMenu = true;
        [Tooltip("Create the procedural audio director (engines, tyres, water, weather, ambience, UI sounds - all synthesized in code).")]
        public bool installAudio = true;
        [Tooltip("Create the VFX director (wheel spray, exhaust, rain, water surface, sky and lighting).")]
        public bool installVfx = true;

        void Start()
        {
            var gm = GameManager.Instance;
            if (gm == null)
            {
                var go = new GameObject("GameManager");
                gm = go.AddComponent<GameManager>();
            }
            UiRoot ui = installUi ? UiBootstrap.Install() : null;
            if (installAudio) AudioDirector.Install();
            if (installVfx) MudRunner.Vfx.VfxDirector.Install();
            if (MudRunner.Testing.PlayerAutomation.Active) { world = MudRunner.Testing.PlayerAutomation.World; vehicle = MudRunner.Testing.PlayerAutomation.Vehicle; }
            if (autoStart) gm.StartWorld(world, vehicle);
            GameSession.VehicleKey = vehicle; GameSession.World = world;
            if (ui != null && showMainMenu && GameSession.ShowMainMenuOnStart) ui.OpenMainMenu();
            MudRunner.Testing.PlayerAutomation.Attach();
        }
    }
}
